// =============================================================================
// Building Operations Control Room — demo configuration & data model.
//
// One fictional site / building with a few zones, three mechanical assets
// (chiller, pump, AHU) and two security devices (door contact, access panel).
//
// SYNTHETIC DATA ONLY. Nothing here controls physical equipment. All telemetry
// is generated by the deterministic simulator in `simulator.ts` and written to
// a native MongoDB time-series collection; anomalies are detected by a real
// backend rolling-window aggregation, not by the frontend or the fault button.
// =============================================================================

/** Collection names — namespaced `bops_` so they never collide with the
 *  existing retrieval-demo collections in the same database. */
export const BOPS = {
  telemetry: "bops_telemetry", // native time-series
  assets: "bops_assets",
  events: "bops_events",
  incidents: "bops_incidents",
  knowledge: "bops_knowledge",
  runs: "bops_runs", // small per-demo-run config records (session isolation)
} as const;

/** Atlas Search index names for the knowledge collection. */
export const BOPS_INDEXES = {
  knowledgeVector: "bops_knowledge_vector", // autoEmbed vector index
  knowledgeLexical: "bops_knowledge_lexical", // Atlas Search lexical index
} as const;

