// -----------------------------------------------------------------------------
// Signals — precise names + units. Used for labels and ingestion validation.
// -----------------------------------------------------------------------------
export interface SignalDef {
  key: string; // field name stored in telemetry readings
  label: string;
  unit: string;
  /** Additive signals are only written after a presenter enables them; history
   *  before activation is genuinely absent (rendered "unavailable", never 0). */
  additive?: boolean;
}

export const SIGNALS = {
  leavingChilledWaterTempC: {
    key: "leavingChilledWaterTempC",
    label: "Leaving chilled-water temperature",
    unit: "°C",
  },
  compressorVibrationMmS: {
    key: "compressorVibrationMmS",
    label: "Compressor vibration",
    unit: "mm/s",
  },
  electricalInputPowerKw: {
    key: "electricalInputPowerKw",
    label: "Electrical input power",
    unit: "kW",
  },
  differentialPressureKpa: {
    key: "differentialPressureKpa",
    label: "Differential pressure",
    unit: "kPa",
    additive: true,
  },
  flowRateLps: { key: "flowRateLps", label: "Flow rate", unit: "L/s" },
  supplyAirTempC: { key: "supplyAirTempC", label: "Supply air temperature", unit: "°C" },
} as const satisfies Record<string, SignalDef>;

export type SignalKey = keyof typeof SIGNALS;

// -----------------------------------------------------------------------------
// Anomaly rule — a single, understandable rolling-window rule. NOT a rules
// engine. Versioned so incident evidence can record which rule fired.
// -----------------------------------------------------------------------------
export const ANOMALY_RULE = {
  id: "chiller-cooling-degradation",
  version: "1.2.0",
  name: "Chiller cooling-performance degradation",
  /** Signal whose rolling baseline is compared against the current reading. */
  primarySignal: "leavingChilledWaterTempC" as SignalKey,
  /** Baseline window (seconds) BEFORE the current observation. The current
   *  observation is excluded from its own baseline (range ends at -5s). */
  baselineWindowSeconds: 600, // ~10 min rolling baseline
  baselineExcludeRecentSeconds: 5,
  /** Absolute rise over baseline mean (°C) that counts as a breach. */
  thresholdDeltaC: 1.6,
  /** Minimum valid samples in the baseline window before the rule may fire
   *  (warm-up guard). */
  minBaselineSamples: 30,
  /** Consecutive breaching samples required to raise an incident (noise guard). */
  consecutiveBreaches: 4,
  /** Supporting signals shown in evidence (not required to breach). */
  supportingSignals: [
    "compressorVibrationMmS",
    "electricalInputPowerKw",
  ] as SignalKey[],
} as const;

// -----------------------------------------------------------------------------
// Correlation — same building + zone, event-time window around detection.
// Temporal/spatial correlation is CONTEXT, not causation.
// -----------------------------------------------------------------------------
export const CORRELATION = {
  windowSecondsBefore: 300, // ~5 min before detection
  windowSecondsAfter: 300, // ~5 min after detection
} as const;

// -----------------------------------------------------------------------------
// Telemetry cadence & retention.
// -----------------------------------------------------------------------------
export const TELEMETRY = {
  /** Live sampling interval (ms). Aligned with real UTC timestamps. */
  intervalMs: 5000,
  /** Minutes of normal history pre-seeded on run start. */
  seedHistoryMinutes: 15,
  /** Granularity for the time-series collection. "seconds" buckets suit a
   *  5s cadence. */
  granularity: "seconds" as const,
  /** TTL for generated telemetry (demo isolation). Applied to the time field;
   *  for time-series, expiry is bucket-based and asynchronous. */
  expireAfterSeconds: 60 * 60 * 24, // 24h — generous; reset switches runs instantly
  /** Data is considered stale if the newest reading is older than this. */
  staleAfterMs: 20000,
} as const;

// -----------------------------------------------------------------------------
// Asset catalog (seeded). Each asset embeds heterogeneous nested specs — the
// document-flexibility story. Common identity envelope + type-specific `specs`
// and `points`. Location is embedded (single seeded building; no hierarchy
// collections).
// -----------------------------------------------------------------------------
export type AssetType = "chiller" | "pump" | "ahu" | "door_contact" | "access_panel";
export type SystemName = "chilled_water" | "air_handling" | "security";

export interface PointDef {
  key: string; // matches a SignalDef key for mechanical assets
  label: string;
  unit: string;
  additive?: boolean;
}

export interface AssetSeed {
  assetId: string;
  type: AssetType;
  system: SystemName;
  name: string;
  vendor: string;
  model: string;
  zoneId: string;
  /** Heterogeneous, type-specific specifications. Deliberately NOT a fixed
   *  shared field set. */
  specs: Record<string, unknown>;
  /** Point (signal) definitions this asset reports. Mechanical assets only. */
  points: PointDef[];
  /** Small bounded maintenance context. */
  maintenance?: {
    lastServiced?: string;
    intervalDays?: number;
    note?: string;
  };
}

const P = (s: SignalDef): PointDef => ({
  key: s.key,
  label: s.label,
  unit: s.unit,
  additive: s.additive,
});

